insert into public.products (id, slug, name, image, images, category, price, sale_price, featured, is_new, description, material, dimensions, status) values
(1, 'don-luc-binh-bv862', 'Đôn lục bình BV862', 'https://maytrelucbinh.com/data/news/2211/don-%20luc-%20binh.jpg', '["https://maytrelucbinh.com/data/news/2211/don-%20luc-%20binh.jpg"]'::jsonb, 'san-pham-khac', 'Liên hệ - 0934 086 085', null, true, true, 'Mã sản phẩm: BV862  Miêu Tả : SẢN PHẨM : ĐÔN GHẾ LỤC BÌNH Chất liệu: Vỏ ngoài: Lục bình Bên trong: xốp, giữ dáng đôn lâu bền Cách sử dụng: - Dùng làm ghế ngồi, có thể chồng hai ghế lên để làm bàn uống trà…. - Đặt những vật dụng trang trí lên trên như lọ hoa, tượng, bình gốm…tại các vị trí khác nhau trong phòng khách, cửa hàng, quán cafe. Màu sắc: màu tự nhiên của thân lục bình Có 2 loại: đôn cao và đôn thấp Hướng dẫn bảo quản: Tuổi thọ đôn phụ thuộc vào cách sử dụng & bảo quản. Nên tránh để nơi ẩm mốc, cần lau sạch hoặc giặt rửa trực tiếp dưới vòi nước khi bị ẩm mốc. Sau đó, mang phơi thật khô là có thể sử dụng lại. Công dụng: Vừa làm bàn trà , vừa làm ghế , có thể ngồi thấp, hay kê chân hoặc trang trí điểm nhấn làm cho không gian của bạn trở nên khác biệt. Số Lượng :', 'Mây tre tự nhiên / lục bình / nhựa giả mây / khung sắt sơn tĩnh điện tùy mẫu', 'Sản xuất theo yêu cầu', 'active'),
(2, 'ban-ghe-don-luc-binh-bv830', 'Bàn ghế đôn lục bình BV830', 'https://maytrelucbinh.com/data/news/2178/don-luc-binh.jpg', '["https://maytrelucbinh.com/data/news/2178/don-luc-binh.jpg"]'::jsonb, 'san-pham-khac', 'Liên hệ - 0934 086 085', null, true, true, 'Mã sản phẩm: BV830  Miêu Tả : Bàn ghế đôn lục bình... nhỏ nhắn, xinh đẹp phù hợp với căn hộ, phòng khách nhỏ, quán trà đạo, hay những studio, shop thời trang chụp hình, hoặc gia đình lấy thêm cho sofa phòng khách,... Chất liệu lục bình tự nhiên hoàn toàn,bên trong nhồi bông xốp nên ngồi rất êm. Ghế đôn cao, ghế đôn thấp, bàn tròn đều có đủ cả và đang được chưng bày tại tiệm nha. Số Lượng :', 'Mây tre tự nhiên / lục bình / nhựa giả mây / khung sắt sơn tĩnh điện tùy mẫu', 'Sản xuất theo yêu cầu', 'active'),
(3, 'thung-de-do-luc-binh-kv80', 'Thùng để đồ lục bình KV80', 'https://maytrelucbinh.com/data/news/1667/Th%C3%B9ng%20%C4%91%E1%BB%83%20%C4%91%E1%BB%93%20l%E1%BB%A5c%20b%C3%ACnh%20KV80%20(1).jpg', '["https://maytrelucbinh.com/data/news/1667/Th%C3%B9ng%20%C4%91%E1%BB%83%20%C4%91%E1%BB%93%20l%E1%BB%A5c%20b%C3%ACnh%20KV80%20(1).jpg","https://maytrelucbinh.com/data/news/1667/Th%C3%B9ng%20%C4%91%E1%BB%83%20%C4%91%E1%BB%93%20l%E1%BB%A5c%20b%C3%ACnh%20KV80%20(2).jpg","https://maytrelucbinh.com/data/news/1667/Th%C3%B9ng%20%C4%91%E1%BB%83%20%C4%91%E1%BB%93%20l%E1%BB%A5c%20b%C3%ACnh%20KV80%20(3).jpg"]'::jsonb, 'san-pham-khac', 'Liên hệ - 0934 086 085', null, true, true, 'Mã sản phẩm:  Miêu Tả : Thùng lục bình để đồ khô, vạt dụng trong khách san, resort Chất liệu: khugn sắt hoặc khung gỗ, đan dây lục bình khô kiểu đan : kéo ngang Kích thước : bộ 3 thùng, với 3 kích thước khác nhau Số Lượng : Thùng lục bình để đồ khô, vật dụng trong khách san, resort Chất liệu: khung sắt hoặc khung gỗ, đan dây lục bình khô kiểu đan : xương cá Kích thước : bộ 3 thùng, với 3 kích thước khác nhau Có nắp đậy mở', 'Mây tre tự nhiên / lục bình / nhựa giả mây / khung sắt sơn tĩnh điện tùy mẫu', 'Sản xuất theo yêu cầu', 'active'),
